	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/templates/system/blank", wrapper.GetSystemBlankTemplate)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/templates/{id}", wrapper.GetTemplate)
